function resolveJsonSchemaStrictSampling(
	tool: Tool,
	supportsStrictMode: boolean,
	disablePreferredStrictTools = false,
): boolean | undefined {
	const config = tool.constrainedSampling;
	if (!config || config.type !== "json_schema") return undefined;
	if (disablePreferredStrictTools && config.strict === "prefer") return undefined;
	if (supportsStrictMode) {
		try {
			makeAnthropicStrictSchema(tool.parameters);
			return true;
		} catch (error) {
			if (!(error instanceof UnsupportedStrictSchemaError)) throw error;
			if (config.strict !== "require") return undefined;
